import { useContext, useEffect, useState } from 'react';
import { AuthContext } from '../../context/authContext';
import axios from 'axios';
import './notifications.scss';

const Notifications = () => {
  const { currentUser } = useContext(AuthContext);
  const [friendRequests, setFriendRequests] = useState([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  useEffect(() => {
    const fetchFriendRequests = async () => {
      setLoading(true);
      setError(null);
      const token = localStorage.getItem('token');
      if (!token) {
        setError('Please log in to view notifications.');
        setLoading(false);
        return;
      }

      try {
        console.log('Fetching from URL: http://localhost:5000/api/users/friend-requests/pending');
        console.log('Token:', token);
        const res = await axios.get('http://localhost:5000/api/users/friend-requests/pending', {
          headers: { Authorization: `Bearer ${token}` },
        });
        console.log('Notifications: Friend requests:', res.data);
        setFriendRequests(res.data);
        setError(null);
      } catch (err) {
        console.error('Notifications: Error fetching friend requests:', err);
        console.error('Response:', err.response?.data);
        const errorMessage = err.response?.data?.message || 'Failed to load notifications.';
        setError(errorMessage);
        setFriendRequests([]);
      } finally {
        setLoading(false);
      }
    };

    if (currentUser) {
      fetchFriendRequests();
    }
  }, [currentUser]);

  const handleFriendRequestAction = async (senderId, action) => {
    try {
      const token = localStorage.getItem('token');
      const res = await axios.post(
        `http://localhost:5000/api/users/friend-requests/${senderId}`,
        { action },
        { headers: { Authorization: `Bearer ${token}` } }
      );
      console.log(`Notifications: Friend request ${action}ed:`, res.data);
      setFriendRequests(friendRequests.filter((req) => req.senderId._id !== senderId));
      alert(`Friend request ${action}ed successfully!`);
    } catch (err) {
      console.error(`Notifications: Error ${action}ing friend request:`, err);
      const errorMessage = err.response?.data?.message || `Failed to ${action} friend request.`;
      setError(errorMessage);
    }
  };

  const getProfilePictureUrl = (profilePicture) => {
    if (!profilePicture) {
      console.log('Notifications: No profile picture provided, using default');
      return '/default-avatar.png';
    }
    if (profilePicture.startsWith('http')) {
      console.log('Notifications: Using external profile picture URL:', profilePicture);
      return profilePicture;
    }
    const normalizedPath = profilePicture.replace(/^\/Uploads\//i, '/Uploads/');
    const url = `http://localhost:5000${normalizedPath}?t=${new Date().getTime()}`;
    console.log('Notifications: Profile picture URL:', url);
    fetch(url)
      .then((res) => console.log('Notifications: User image fetch status:', res.status, res.statusText))
      .catch((err) => console.error('Notifications: User image fetch error:', err));
    return url;
  };

  if (!currentUser) {
    return <div className="notifications">Please log in to view notifications.</div>;
  }

  return (
    <div className="notifications">
      <h3>Notifications</h3>
      {loading && <p className="loading">Loading...</p>}
      {error && <p className="error">{error}</p>}
      {friendRequests.length === 0 && !loading && !error && (
        <p className="no-requests">No pending friend requests.</p>
      )}
      <div className="requests-list">
        {friendRequests.map((request) => (
          <div key={request.senderId._id} className="request-card">
            <div className="request-info">
              <img
                src={getProfilePictureUrl(request.senderId.profilePicture)}
                alt={`${request.senderId.username}'s profile`}
                className="avatar"
                onError={(e) => {
                  console.error(`Notifications: Image load error for ${request.senderId.username}:`, e);
                  e.target.src = '/default-avatar.png';
                }}
              />
              <div className="details">
                <span className="username">{request.senderId.username}</span>
                <span className="name">{request.senderId.name} sent you a friend request</span>
              </div>
            </div>
            <div className="actions">
              <button
                className="accept-btn"
                onClick={() => handleFriendRequestAction(request.senderId._id, 'accept')}
                disabled={loading}
              >
                Accept
              </button>
              <button
                className="reject-btn"
                onClick={() => handleFriendRequestAction(request.senderId._id, 'reject')}
                disabled={loading}
              >
                Reject
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default Notifications;
